window.docContents[184].resolve({"/Iwasawa-theory-for-modular-forms/#An-introduction-to-p-adic-L-functions-___-Lean-blueprint--Iwasawa-theory-for-modular-forms":{"contents":"The Kubota–Leopoldt picture of Parts I and II is the Iwasawa theory of\n: Dirichlet characters are the algebraic automorphic forms for\n, and  is their -adic -function. The next case is\n, whose automorphic forms are modular forms. Remarkably, all of the\n theory has a  analogue for sufficiently nice modular forms,\nalthough the picture is not yet complete in full generality. This chapter\nrecords the three constructions and the comparison theorems that bind them.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"An introduction to p-adic L-functions — Lean blueprint","header":"14. Iwasawa theory for modular forms","id":"/Iwasawa-theory-for-modular-forms/#An-introduction-to-p-adic-L-functions-___-Lean-blueprint--Iwasawa-theory-for-modular-forms"}});